<script lang="ts">import {goto} from '$app/navigation';import Heading from '$lib/components/Heading.svelte';import Icon from '$lib/components/Icon.svelte';import Stat from '$lib/components/Stat.svelte';import StorageForm from '$lib/components/files/StorageForm.svelte';import {fileState} from '$lib/files/store';import {sizeLabel,treeBytes} from '$lib/files/model.js';let show=false,query='';$: rows=$fileState.spaces.filter(s=>s.name.toLowerCase().includes(query.trim().toLowerCase()));$: total=$fileState.spaces.reduce((n,s)=>n+treeBytes(s.files),0);</script>
<Heading title="Storage" subtitle="Create separate spaces for images, documents, media and application uploads."><button class="btn primary" on:click={()=>show=!show}><Icon name="Plus"/> New storage space</button></Heading><div class="stack"><div class="grid3"><Stat label="Storage spaces" value={$fileState.spaces.length} icon="Storage" hint="Independent resources"/><Stat label="Used space" value={sizeLabel(total)} icon="File" hint="Browser sample files"/><Stat label="Total quota" value={$fileState.spaces.reduce((n,s)=>n+s.quota,0)+' MB'} icon="Storage" hint="Illustrative limit"/></div>{#if show}<StorageForm onSaved={(id)=>{show=false;void goto('/file-manager?target='+encodeURIComponent('space:'+id));}} onCancel={()=>show=false}/>{/if}<section class="card table-card"><div class="table-head"><h3>Storage spaces</h3><div class="toolbar"><label class="search"><Icon name="Search"/><input bind:value={query} placeholder="Search storage spaces…" aria-label="Search storage spaces"/></label></div></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Usage</th><th>Access</th><th>Actions</th></tr></thead><tbody>{#each rows as s}<tr><td><a class="link-btn" href={'/storage/'+s.id}>{s.name}</a></td><td>{sizeLabel(treeBytes(s.files))} / {s.quota} MB</td><td>{s.access}</td><td><div class="table-actions"><a class="btn secondary small" href={'/file-manager?target='+encodeURIComponent('space:'+s.id)}>Open files</a><a class="btn secondary small" href={'/storage/'+s.id}>Manage</a></div></td></tr>{:else}<tr><td colspan="4">No storage spaces found.</td></tr>{/each}</tbody></table></div></section></div>
